failed_experiment.source:
#include "crypto_montgomery_ct.h"
#include <errno.h>
#include <string.h>
extern limb_t nondet_limb(void);
int crypto_montgomery_ctx_init(crypto_montgomery_ctx *ctx, const limb_t *modulus, size_t n)
{
  if ((((!ctx) || (!modulus)) || (n == 0)) || (n > CRYPTO_MAX_LIMBS))
  {
    errno = EINVAL;
    return -1;
  }
  limb_t upper = 0;
  for (size_t i = 1; i < n; ++i)
    upper |= modulus[i];

  if ((!(modulus[0] & 1)) || ((upper == 0) && (modulus[0] <= 1)))
  {
    errno = EDOM;
    return -1;
  }
  limb_t inv = 1;
  inv = nondet_limb();
  ctx->limbs = 0; ctx->inverse = 0;
  for (size_t w = 0; w < CRYPTO_MAX_LIMBS; ++w) ctx->modulus[w] = 0;
  for (size_t w = 0; w < n; ++w) ctx->modulus[w] = modulus[w];
  ctx->inverse = ((limb_t) 0) - inv;
  ctx->limbs = n;
  errno = 0;
  return 0;
}
